  triggers: [
    {
      id: "station",
      x: 24,
      y: 44,
      w: 27,
      h: 10,
      text: "The top station: the car stops against a buffer of white steel with a sigh, and the doors open on air that smells of nothing at all. Ahead, across the whole of the rim, a screen of steel and glass, and one arch in it with a lens at its crown. Through the glass, green: trees in rows, real ones, and light that has never had dust in it.",
      effects: [
        {
          learn: "hc_station_seen"
        },
        {
          learn: "seen_halcyon"
        }
      ]
    },
    {
      id: "road",
      x: 1,
      y: 36,
      w: 6,
      h: 9,
      text: "The road comes up the last bend and through a cut in the rim, and there is the Clean's post: a lamp, a board, two of them in grey with nothing on their boots. Past them, a yard of sheds and barrows and compost, and the white screen of Halcyon running along the rim, and through it, green.",
      effects: [
        {
          learn: "hc_road_seen"
        },
        {
          learn: "seen_halcyon"
        }
      ]
    },
    {
      id: "yard",
      x: 8,
      y: 30,
      w: 14,
      h: 8,
      text: "The service yard. Barrows, sacks of compost, a hose. A low iron door under the screen with a lens beside it, and a bench along the wall where, at dawn, the gardeners from the Skirts wait to be let in.",
      effects: [
        {
          learn: "hc_yard_seen"
        }
      ]
    },
    {
      id: "inside",
      x: 1,
      y: 1,
      w: 70,
      h: 28,
      text: "Inside. The air is warm and wet and smells of leaves. Fruit trees in tubs in rows down the paths, a man sweeping leaves that have not fallen yet, rain pipes along the glass overhead. People in clean clothes walk past without looking at you, and nobody among them who is old looks old.",
      effects: [
        {
          set: "hc_inside"
        },
        {
          learn: "hc_inside_seen"
        },
        {
          quest: "q_hc_longlived",
          start: true
        }
      ]
    },
    {
      id: "concourse",
      x: 23,
      y: 34,
      w: 30,
      h: 9,
      text: "The concourse inside the arch: white floor, benches nobody sits on, two of the Clean, and on an easel a card in a frame: THE BOARD'S BALL \u2014 THE SEASON'S RENEWAL \u2014 ON THE BOARD'S FLOOR, WHEN THE DESIGNATE IS PLEASED TO ATTEND.",
      effects: [
        {
          set: "hc_inside"
        },
        {
          learn: "hc_inside_seen"
        },
        {
          learn: "hc_ball_card"
        },
        {
          quest: "q_hc_longlived",
          start: true
        }
      ]
    },
    {
      id: "clinicword",
      x: 23,
      y: 34,
      w: 30,
      h: 9,
      if: {
        all: [
          {
            flag: "hs_nils",
            eq: "up"
          },
          {
            not: {
              flag: "hc_nils"
            }
          }
        ]
      },
      text: "A gardener with Skirts hands goes past you with a barrow and says, without stopping or looking at you, \"Joran's boy is on nine. The Chair's list. Before the ball.\" Then she is gone up the path.",
      effects: [
        {
          learn: "hc_nils_listed"
        }
      ]
    }
  ],
